public long countInversions(int[] nums) {
    int[] buffer = new int[nums.length];
    return mergeSort(nums, buffer, 0, nums.length - 1);
}

private long mergeSort(int[] a, int[] buf, int lo, int hi) {
    if (lo >= hi) {
        return 0;
    }
    int mid = lo + (hi - lo) / 2;
    long count = mergeSort(a, buf, lo, mid) + mergeSort(a, buf, mid + 1, hi);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {        // <= so equals are NOT inversions
            buf[k++] = a[i++];
        } else {
            buf[k++] = a[j++];
            count += (mid - i + 1); // all remaining left elements > a[j]
        }
    }
    while (i <= mid) buf[k++] = a[i++];
    while (j <= hi)  buf[k++] = a[j++];
    System.arraycopy(buf, lo, a, lo, hi - lo + 1);
    return count;
}

